        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_bd_apv') }}
    where HUB_POLICY_K0__EMIT
    union all
    select
        md5(upper(HUB_POLICY_BK__K0)) as HUB_POLICY_HK,
        null::varchar as DEDUCTIBLE_TOTAL,
        null::varchar as CO_PAYMENT_PERCENTAGE,
